// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 seed) public {
        // The caller must be a contract (Bank) that returns the expected token hash,
        // so deploy an adversarial helper embodying that counterparty; the fuzzer's seed
        // only scopes the scenario, the deciding check is over c's public balance getter.
        Bank bank = new Bank();
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
        vm.assume(actor != address(0) && actor != address(c));

        vm.prank(address(bank));
        c.airDrop();

        // General rule: any eligible caller receives exactly 20 tokens per airDrop.
        assertTrue(c.tokenBalance(address(bank)) == 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}
